#!/usr/bin/env python3
"""Text-only, single-file Phase A SDK build repair. No binary archives."""
import argparse,base64,hashlib,json,pathlib,sys
PAYLOAD=''
EXPECTED={'phase_a/Makefile': '020a43267ed38f3bccd6e2c70d57b6686187d5e6f589d129d7ceab30c460325f', 'phase_a/main.c': '4ccfe0b9157b63c3cde44403f4c999da4b890a08e06fbe0e5bffedd713c720f0', 'phase_a/check_rom.py': '7e64603007fdc88cdc5cb2ff77ed80ced482bf83da7974fa40473e6e84c99e22', '.github/workflows/re3-phase-a.yml': '35b558e224f724a0aae7573b989f72354943614fd2e24a9eb70f7547f704c02f', 'phase_a/PHASE_A_FIX_README.md': '43ba414a8a9db5debd3a2b707c08a90a3c6e3c0763df568140236c14f9ea889e'}
def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('--verify',action='store_true')
    ap.add_argument('--install',action='store_true')
    ap.add_argument('--replace',action='store_true',help='Explicitly replace differing generated files after review')
    args=ap.parse_args()
    if not (args.verify or args.install): ap.error('Specify --verify or --install')
    files=json.loads(base64.b64decode(PAYLOAD).decode())
    for path,content in files.items():
        assert hashlib.sha256(content.encode()).hexdigest()==EXPECTED[path],path
    print('PASS:',len(files),'embedded files verified')
    if args.install:
        for path,content in files.items():
            p=pathlib.Path(path)
            if p.exists() and p.read_bytes()!=content.encode() and not args.replace:
                print('CONFLICT: refusing to overwrite',path,file=sys.stderr)
                return 2
        for path,content in files.items():
            p=pathlib.Path(path);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
            print('INSTALLED',path)
    return 0
if __name__=='__main__':sys.exit(main())
